function esc(value) {
  return String(value).replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' })[c]);
}

function inline(markdown) {
  let text = esc(markdown);
  text = text.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer">$1</a>');
  text = text.replace(/`([^`]+)`/g, '<span class="mono">$1</span>');
  text = text.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  const labels = { Official: 'official', 'On-chain': 'onchain', Reporting: 'media', Inference: 'infer', Community: 'rumor' };
  text = text.replace(/\[(Official|On-chain|Reporting|Inference|Community)\]/g, (_, label) => `<span class="label ${labels[label]}">[${label}]</span>`);
  return text;
}

function markdown(markdownText) {
  const lines = String(markdownText || '').split(/\r?\n/);
  const out = [];
  let list = null;
  let paragraph = [];
  const flush = () => { if (paragraph.length) { out.push(`<p>${inline(paragraph.join(' '))}</p>`); paragraph = []; } };
  const close = () => { if (list) { out.push(`</${list}>`); list = null; } };
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { flush(); close(); continue; }
    const h3 = line.match(/^###\s+(.+)$/);
    if (h3) { flush(); close(); out.push(`<h3>${inline(h3[1])}</h3>`); continue; }
    const bullet = line.match(/^[-*]\s+(.+)$/);
    const ordered = line.match(/^\d+\.\s+(.+)$/);
    if (bullet || ordered) {
      flush();
      const type = bullet ? 'ul' : 'ol';
      if (list !== type) { close(); list = type; out.push(`<${type}>`); }
      out.push(`<li>${inline((bullet || ordered)[1])}</li>`);
      continue;
    }
    paragraph.push(line);
  }
  flush(); close();
  return out.join('\n');
}

function table(headers, rows) {
  return `<div class="table-wrap"><table><thead><tr>${headers.map((header) => `<th>${esc(header)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((cell) => `<td>${inline(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function addAlternates(html, canonical, english) {
  if (html.includes('hreflang="en"')) return html;
  const tag = `<link rel="canonical" href="${canonical}">`;
  return html.replace(tag, `${tag}\n  <link rel="alternate" hreflang="zh-CN" href="${canonical}">\n  <link rel="alternate" hreflang="en" href="${english}">\n  <link rel="alternate" hreflang="x-default" href="${canonical}">`);
}

function sourceList(hrefs, names, className) {
  return `<ul class="${className}">${hrefs.map((href, i) => `<li><a href="${esc(href)}" target="_blank" rel="noreferrer">${esc(names[i] || `Source ${i + 1}`)}</a></li>`).join('')}</ul>`;
}

function extractHrefs(html, pattern) {
  return [...html.matchAll(pattern)].map((match) => match[1]);
}

