  const hero = `<header class="hero"><div class="wrap"><div style="display:flex;justify-content:space-between;align-items:center;gap:16px"><a class="siteback" href="../../../en/">← Report archive</a><a class="siteback" href="../" style="border:1px solid rgba(255,255,255,.3);padding:4px 10px;border-radius:999px">中文</a></div><div class="eyebrow">Event Risk / Protocol Solvency / Oracle Manipulation</div><h1>Tectonic Incident Risk Report</h1><p>A conclusion more important than “a roughly $74 million attack”: traceable attacker assets and the Tectonic attack position's on-chain shortfall use different denominators. This report separates official statements, reproducible chain evidence and unresolved questions.</p><div class="stamp"><span>v1 · 2026-08-31</span><span>Cutoff 09:59:15 CST (+08:00)</span><span>Cronos block 90,907,150</span><span>Ethereum block 25,872,114</span></div></div></header>`;
  english = english.replace(/<header class="hero">[\s\S]*?<\/header>/,hero);
  const nav = `<nav class="toc"><strong>Contents</strong>${Object.entries({s1:'1. Cutoff',s2:'2. Executive Summary',s3:'3. Scope and evidence',s4:'4. Product and strategy',s5:'5. Balance sheet',s6:'6. Timeline and path',s7:'7. Protocol status',s8:'8. Impact perimeter',s9:'9. Live exposure',s10:'10. Liquidity and liquidation',s11:'11. Recovery scenarios',s12:'12. Historical cases',s13:'13. Sentiment',s14:'14. Independent view',s15:'15. Actions and monitoring',s16:'16. Caveats and sources'}).map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav>`;
  english = english.replace(/<nav class="toc">[\s\S]*?<\/nav>/,nav);
  for (const [id, replacement] of Object.entries(sections)) english = english.replace(new RegExp(`<section class="section" id="${id}">[\\s\\S]*?<\\/section>`),replacement);
  english = english.replace(/<div class="wrap footer">[\s\S]*?<\/div>/,'<div class="wrap footer"><a href="../../../en/">On-chain Incident Risk Report Archive</a> · Tectonic Incident Risk Report · v1 · Evidence cutoff 2026-08-31</div>');
  const out = path.join(reportDir,'en/index.html'); fs.mkdirSync(path.dirname(out),{recursive:true}); fs.writeFileSync(out,english);
