  const englishUrl = `${canonical}en/`;
  chinese = addAlternates(chinese, canonical, englishUrl);
  if (!chinese.includes('href="en/"')) chinese = chinese.replace('← 返回报告档案</a>','← 返回报告档案</a><a href="en/" style="display:inline-block;color:#fff;margin-left:12px;font-size:12px;border:1px solid rgba(255,255,255,.35);padding:4px 9px;border-radius:999px;position:relative;z-index:1">English</a>');
